import * as T from './vendor/three.module.min.js';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
// This is the original alley stream construction expanded into a fountain fan:
// two crossed ribbons per arc, a scrolling generated streak map, no particles.
export function createGardenSprinklers85(scene,texture,onFaceSpray,mistTexture=texture){const root=new T.Group();root.name='V86 intermittent fans / crossed scrolling water ribbons';scene.add(root);let seed=0x86173;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 const sources=[[[7.83,1.65,-2.79],[6.9,2.65,-2.79],[5.85,.05,-2.94]],[[7.80,1.15,1.20],[6.80,4.15,1.4],[5.95,.05,1.2]],[[-7.86,1.40,-3.0],[-6.85,4.55,-3.0],[-5.65,.04,-3.2]],[[-7.70,1.0,-6.5],[-6.6,4.1,-6.5],[-5.35,.06,-6.6]],[[3.0,1.2,-9.38],[3.1,4.7,-8.25],[3.4,.07,-6.8]],[[-2.2,1.0,-9.4],[-2.6,4.25,-8.05],[-2.8,.05,-6.25]]];
 function ribbon(pts,width){const curve=new T.QuadraticBezierCurve3(...pts),ribbons=[];for(let cross=0;cross<2;cross++){const p=[],uv=[],ix=[];for(let j=0;j<=28;j++){const t=j/28,q=curve.getPoint(t),tan=curve.getTangent(t).normalize(),side=new T.Vector3(-tan.z,0,tan.x).normalize();if(cross)side.cross(tan).normalize();const w=width*(.75+.52*t);for(const s of[-1,1]){p.push(q.x+side.x*s*w,q.y+side.y*s*w,q.z+side.z*s*w);uv.push(s<0?0:1,1-t);}if(j<28){const a=j*2;ix.push(a,a+1,a+2,a+1,a+3,a+2);}}const g=new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(p,3)).setAttribute('uv',new T.Float32BufferAttribute(uv,2)).setIndex(ix);g.computeVertexNormals();ribbons.push(g);}const g=mergeGeometries(ribbons);ribbons.forEach(g=>g.dispose());return g;}
 const records=[];for(let index=0;index<sources.length;index++){const pts=sources[index].map(p=>new T.Vector3(...p)),map=texture.clone();map.wrapS=map.wrapT=T.RepeatWrapping;map.repeat.set(1,3.1);map.needsUpdate=true;const material=new T.MeshBasicMaterial({map,color:0xe4faff,transparent:true,opacity:.86,side:T.DoubleSide,depthWrite:false});
 // Preserve the old generated streak alpha, remove its ochre pigment in shader.
 material.onBeforeCompile=s=>{s.fragmentShader=s.fragmentShader.replace('#include <map_fragment>',`#include <map_fragment>\nfloat waterValue=dot(diffuseColor.rgb,vec3(.299,.587,.114));diffuseColor.rgb=mix(vec3(.55,.77,.84),vec3(.97,1.,1.),waterValue);`);};material.customProgramCacheKey=()=> 'v86-white-water-from-original-stream';material.forceSinglePass=true;
 const group=new T.Group();root.add(group);const arcs=[];for(let j=0;j<9;j++){const delta=(j-4)*.115,a=pts[0].clone(),b=pts[1].clone(),c=pts[2].clone();if(j!==4){const aim=c.clone().sub(a),side=new T.Vector3(-aim.z,0,aim.x).normalize();b.addScaledVector(side,delta*.9);c.addScaledVector(side,delta*2.7);b.y+=(index===0?1.8:0)+Math.sin(j*1.9+index)*.34;c.addScaledVector(aim,(rnd()-.5)*.2);}arcs.push(ribbon([a,b,c],.0065+rnd()*.0055));}
 const geom=mergeGeometries(arcs);arcs.forEach(g=>g.dispose());const stream=new T.Mesh(geom,material);stream.name='Nine crossed parabolic strands / sprinkler '+index;group.add(stream);const mist=[];
 for(let j=0;j<6;j++){const m=new T.SpriteMaterial({map:mistTexture,color:0xc6e8eb,transparent:true,opacity:0,depthWrite:false,rotation:rnd()*TAU}),sprite=new T.Sprite(m),target=index===0&&j<3?new T.Vector3(6.81,1.70,-2.8):pts[2];sprite.position.copy(target).add(new T.Vector3((rnd()-.5)*.55,.12+(j%3)*.15,(rnd()-.5)*.55));sprite.scale.setScalar(.39+j*.06);group.add(sprite);mist.push(sprite);}group.visible=false;records.push({group,stream,map,mist,next:2.6+index*2.15+rnd()*3.8,until:0,active:false,phase:rnd()*TAU});}
 let last=null;return{root,records,update(t){if(last===null){records.forEach(r=>r.next+=t);last=t;}if(t<last||t-last>8)records.forEach((r,i)=>{r.next=t+2+i*1.6+rnd()*3;r.active=false;r.group.visible=false;});last=t;for(let i=0;i<records.length;i++){const r=records[i];if(!r.active&&t>=r.next){r.active=true;r.until=t+2.1+rnd()*2.5;r.group.visible=true;if(i===0)onFaceSpray?.(t+.13);}if(r.active&&t>r.until){r.active=false;r.group.visible=false;r.next=t+8+rnd()*18;}if(r.active){r.map.offset.y=-(t*1.75)%1;for(let j=0;j<r.mist.length;j++){r.mist[j].material.opacity=.14+.10*Math.sin(t*5+r.phase+j)**2;r.mist[j].scale.setScalar(.49+j*.065+.10*Math.sin(t*3+j));}}}},dispose(){root.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});records.forEach(r=>r.map.dispose());root.removeFromParent();}};
}
const TAU=Math.PI*2;
